import{c as e,Q as o,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Claude Code 冷啟動延遲與 Auto-Load 載入優化深度研究報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-03-claude-code-cold-start-latency-deep-research.md","filePath":"research/reports/2026-06-03-claude-code-cold-start-latency-deep-research.md","lastUpdated":1785909234000}'),r={name:"research/reports/2026-06-03-claude-code-cold-start-latency-deep-research.md"};function d(i,t,n,l,h,c){return o(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="claude-code-冷啟動延遲與-auto-load-載入優化深度研究報告" tabindex="-1">Claude Code 冷啟動延遲與 Auto-Load 載入優化深度研究報告 <a class="header-anchor" href="#claude-code-冷啟動延遲與-auto-load-載入優化深度研究報告" aria-label="Permalink to &quot;Claude Code 冷啟動延遲與 Auto-Load 載入優化深度研究報告&quot;">​</a></h1><p><strong>日期</strong>：2026-06-03 | <strong>分支</strong>：<code>feature/autoload-coldstart-research</code><strong>研究方法</strong>：gap-map 去重 → latency 主軸 pivot → 本機實測 → arXiv 接地 → adversarial 校驗 <strong>來源</strong>：官方文件 5 處 · GitHub issues 9 個 · 社群/blog 5 處 · arXiv 全文 2 篇（另 2 篇摘要）· 本機 hook 實測 10+ 點</p><hr><h2 id="執行摘要" tabindex="-1">執行摘要 <a class="header-anchor" href="#執行摘要" aria-label="Permalink to &quot;執行摘要&quot;">​</a></h2><p>前作（2026-05-18 / 05-25 共 9+ 份報告）已徹底覆蓋 <strong>token 重量</strong>維度（auto-load ≤ 3,500 tokens、合規率 76%→52%、TYPE A/B/C/D 分類、defer_loading -85%）。本報告填補<strong>未覆蓋的兩個 GAP</strong>：</p><ol><li><strong>冷啟動 wall-clock latency</strong>（hook 執行時間、session init、MCP 連線）— 前作零覆蓋</li><li><strong>prompt cache 冷→暖機制</strong>對 startup 的影響 — 前作僅覆蓋成本面，缺機制與 deferred-tool 交互</li></ol><p><strong>核心結論</strong>：Claude Code 的啟動與互動延遲，主要不在「載入多少 token」，而在「<strong>每個 hook 各自 spawn 一個 Node.js/bash 進程的 cold-start 開銷</strong>」。社群實測：11+ hooks 可使每 prompt 從 4.8s 暴增至 18–21s（+13–16s）。本機實測同樣指認 hook spawn 與同步 healthcheck 為延遲主因，而非 auto-load token 量。</p><p><strong>最高槓桿動作</strong>（依社群 + 官方 + 本機交叉驗證）：</p><table tabindex="0"><thead><tr><th>優先</th><th>動作</th><th>預期效果</th><th>來源</th></tr></thead><tbody><tr><td>P0</td><td>side-effect hook 加 <code>async: true</code>（v2.1.45+）</td><td>不阻塞 model，回收阻塞延遲</td><td>官方 hooks doc</td></tr><tr><td>P0</td><td><strong>security hook 不可 async</strong> → 改 dispatcher / 內部優化</td><td>保留安全 + 降 spawn</td><td>Lane A #6/#8 + 安全紅線</td></tr><tr><td>P1</td><td>dispatcher 模式合併多 hook</td><td>V8 spawn 50–80ms → IPC ~2–5ms（-94~99%）</td><td>GitHub #26521</td></tr><tr><td>P1</td><td>prompt cache pre-warm（<code>max_tokens:0</code>）</td><td>維持 cache 暖態，避免 resume cache miss</td><td>官方 caching doc</td></tr><tr><td>P2</td><td>MCP project-scoped + 待 <code>lazyConnect</code></td><td>減少 idle server spawn</td><td>GitHub #63251</td></tr></tbody></table><hr><h2 id="_1-研究動機與去重定位" tabindex="-1">1. 研究動機與去重定位 <a class="header-anchor" href="#_1-研究動機與去重定位" aria-label="Permalink to &quot;1. 研究動機與去重定位&quot;">​</a></h2><h3 id="_1-1-為何-pivot-到-latency" tabindex="-1">1.1 為何 pivot 到 latency <a class="header-anchor" href="#_1-1-為何-pivot-到-latency" aria-label="Permalink to &quot;1.1 為何 pivot 到 latency&quot;">​</a></h3><p>使用者首要訴求是「speed up cold start / 提升載入速度」。Gap-map 掃描 9+ 份既有報告 + 60+ 篇 papers，確認：</p><ul><li><strong>已覆蓋</strong>：token-loaded-before-first-turn（auto-load 上限、合規率、cache 成本倍率、deferred token 數字）</li><li><strong>零覆蓋</strong>：startup 的真實 wall-clock 時間 — hook 執行 ms、session init 耗時、MCP 連線延遲、cache 冷→暖端到端時間</li></ul><p>本報告 lead with latency（未服務的維度），token 維度僅引用前作數字接合，不重述。</p><h3 id="_1-2-概念框架-arxiv-接地" tabindex="-1">1.2 概念框架（arXiv 接地） <a class="header-anchor" href="#_1-2-概念框架-arxiv-接地" aria-label="Permalink to &quot;1.2 概念框架（arXiv 接地）&quot;">​</a></h3><p>兩篇 serverless cold-start 論文（雖屬 GPU/serverless 層，概念可遷移）建立本研究的分析框架：</p><ul><li><strong>HydraServe</strong>（arXiv 2502.15524, PKU+Alibaba）：冷啟動延遲可由**架構重疊（overlap stages）與預備（proactive distribution）**消除，降 1.7–4.7×。對應：hook async 化 + cache pre-warm。</li><li><strong>Cold-Start Anti-Patterns</strong>（arXiv 2512.16066, UMich, IEEE SANER 2026）：把 cold-start 當 <strong>developer-visible 設計問題</strong>（非黑盒），從 81 issue reports 推導反模式（redundant imports / deferred one-time init / 大相依打包）。InitScope「loaded vs executed」框架 = 本研究 gap-map 同精神（auto-load 載入的有多少真被執行引用）。商業動機：<strong>Amazon 每 +100ms 損失 1% 銷售</strong>。</li></ul><blockquote><p>誠實標注：cold-start latency 屬系統工程，<strong>Claude Code 專屬的學術文獻薄弱</strong>。上述兩篇為概念類比，非直接研究 Claude Code；本報告主體證據來自官方文件 + GitHub issues + 本機實測。</p></blockquote><hr><h2 id="_2-冷啟動延遲圖譜-本機實測-社群交叉驗證" tabindex="-1">2. 冷啟動延遲圖譜（本機實測 + 社群交叉驗證） <a class="header-anchor" href="#_2-冷啟動延遲圖譜-本機實測-社群交叉驗證" aria-label="Permalink to &quot;2. 冷啟動延遲圖譜（本機實測 + 社群交叉驗證）&quot;">​</a></h2><h3 id="_2-1-本機-hook-實測" tabindex="-1">2.1 本機 hook 實測 <a class="header-anchor" href="#_2-1-本機-hook-實測" aria-label="Permalink to &quot;2.1 本機 hook 實測&quot;">​</a></h3><blockquote><p>方法學（誠實揭露）：<strong>wall-clock，n=3，dummy <code>echo &#39;{}&#39;</code> stdin，cold interpreter 每次</strong>。非生產負載 profiling，數量級可信、絕對值有 ±20% 噪音。</p></blockquote><table tabindex="0"><thead><tr><th>Hook</th><th>觸發時機</th><th>頻率</th><th style="text-align:right;">實測 avg</th><th>性質</th></tr></thead><tbody><tr><td><strong>pre-commit-review.sh</strong></td><td>PreToolUse <code>git commit</code></td><td>低（2 次/7天）</td><td style="text-align:right;"><strong>2,965ms</strong></td><td>低頻高延遲 — 96% 來自同步 <code>healthcheck.sh</code>（單獨 2,854ms）</td></tr><tr><td><strong>session-init.sh</strong></td><td>SessionStart</td><td>每 session 1 次</td><td style="text-align:right;"><strong>592ms</strong></td><td>warm-cache 下 fetch=0ms（cache hit），592ms 主要是 shell init + 26 skill 掃描 + echo；<strong>僅冷 clone 才含 fetch</strong></td></tr><tr><td><strong>user-prompt-submit.sh</strong></td><td>UserPromptSubmit</td><td><strong>每 prompt（阻塞）</strong></td><td style="text-align:right;"><strong>146ms</strong></td><td>高頻中延遲 — 每次互動前阻塞 model</td></tr><tr><td><strong>block-dangerous.sh</strong></td><td>PreToolUse <code>Bash</code></td><td><strong>每次 Bash</strong></td><td style="text-align:right;"><strong>53ms</strong></td><td>高頻低延遲 — 安全 gate，<strong>不可 async</strong></td></tr><tr><td>protect-sensitive-files.sh</td><td>PreToolUse <code>Edit|Write</code></td><td>每次寫檔</td><td style="text-align:right;">56ms</td><td>安全 gate，<strong>不可 async</strong></td></tr><tr><td>pre-compact.sh</td><td>PreCompact</td><td>偶發</td><td style="text-align:right;">73ms</td><td>side-effect</td></tr><tr><td>memory-sync.sh</td><td>(依設定)</td><td>偶發</td><td style="text-align:right;">26ms</td><td>side-effect</td></tr><tr><td><s>sdd-cache-pre.sh</s></td><td>PreToolUse <code>WebFetch</code></td><td>（已於 PR #743 刪除）</td><td style="text-align:right;">33ms</td><td>cache</td></tr></tbody></table><p><strong>關鍵洞察</strong>：</p><ul><li>延遲不來自 auto-load token（16,927 bytes ≈ 4.2K tokens，cache 命中後 0.1× 成本，且不重複載入）</li><li>延遲來自<strong>進程 spawn × 觸發頻率</strong>。block-dangerous 53ms × 每次 Bash = 一個 50-tool-call 的 session 累積 ~2.6s 純 hook 開銷</li><li>pre-commit 的 2,965ms 是低頻但體感最強的「卡住」點</li></ul><h3 id="_2-2-社群實測交叉驗證-lane-a" tabindex="-1">2.2 社群實測交叉驗證（Lane A） <a class="header-anchor" href="#_2-2-社群實測交叉驗證-lane-a" aria-label="Permalink to &quot;2.2 社群實測交叉驗證（Lane A）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>發現</th><th>數字</th><th>來源</th><th>類型</th></tr></thead><tbody><tr><td><code>showSetupScreens()</code> 佔啟動</td><td><strong>3,112ms</strong>（總啟動 3,460ms）</td><td>GitHub #21261</td><td>定量實測</td></tr><tr><td>11+ hooks（9 lifecycle）每 prompt</td><td><strong>18–21s</strong>（無 hook 4.8s，+13–16s）</td><td>ruflo #1530</td><td>定量實測</td></tr><tr><td>每 Node.js process spawn V8 cold-start</td><td><strong>50–80ms</strong></td><td>GitHub #26521</td><td>定量實測</td></tr><tr><td>63 hooks blocking overhead/tool call</td><td><strong>375–525ms</strong></td><td>GitHub #26521</td><td>定量實測</td></tr><tr><td>→ <code>type:&quot;server&quot;</code> IPC hook</td><td><strong>~2–5ms/call（-94~99%）</strong></td><td>GitHub #26521 提案</td><td>原型實測</td></tr><tr><td>95 hooks dispatcher 模式總開銷</td><td><strong>~200ms/event</strong></td><td>blakecrosley.com</td><td>實測</td></tr><tr><td>static-analysis RAG hook wall-clock</td><td><strong>-35.3%（11.80s→7.64s）</strong></td><td>GitHub #53224 / MIT context-os</td><td>定量實測</td></tr><tr><td>Windows <code>tasklist|findstr</code></td><td><strong>599,879ms（~10min）→ 336ms</strong></td><td>GitHub #16257（已修）</td><td>定量實測</td></tr><tr><td>Claude Desktop eager loading 重啟</td><td><strong>30–60s</strong>（清 git-worktrees.json 可解）</td><td>GitHub #38346</td><td>定量實測</td></tr><tr><td>MCP server 全部 eager connect</td><td>無 wall-clock 數字（提案 <code>lazyConnect</code>）</td><td>GitHub #63251</td><td>定性</td></tr><tr><td>HTTP MCP transport/call</td><td>+30–200ms（vs stdio 本地）</td><td>TrueFoundry</td><td>估算</td></tr></tbody></table><p><strong>社群與本機一致結論</strong>：hook 進程 spawn 是 Claude Code 互動延遲的首要可控來源。</p><hr><h2 id="_3-prompt-cache-冷→暖機制-官方明文-lane-b" tabindex="-1">3. Prompt Cache 冷→暖機制（官方明文，Lane B） <a class="header-anchor" href="#_3-prompt-cache-冷→暖機制-官方明文-lane-b" aria-label="Permalink to &quot;3. Prompt Cache 冷→暖機制（官方明文，Lane B）&quot;">​</a></h2><p>前作覆蓋 TTL 5min + 90% discount。本報告補機制：</p><h3 id="_3-1-成本倍率與回本點" tabindex="-1">3.1 成本倍率與回本點 <a class="header-anchor" href="#_3-1-成本倍率與回本點" aria-label="Permalink to &quot;3.1 成本倍率與回本點&quot;">​</a></h3><table tabindex="0"><thead><tr><th>狀態</th><th>成本倍率</th><th>說明</th></tr></thead><tbody><tr><td>Cache write（冷，5min TTL）</td><td><strong>1.25×</strong> base input</td><td>首次寫入</td></tr><tr><td>Cache write（1hr TTL）</td><td><strong>2.0×</strong> base input</td><td><code>ttl:&quot;1h&quot;</code></td></tr><tr><td>Cache read（暖）</td><td><strong>0.1×</strong> base input</td><td>兩種 TTL 皆同</td></tr></tbody></table><ul><li><strong>回本點</strong>：1.25 / (1−0.1) ≈ <strong>1.4 次命中即打平</strong>；≥2 次命中淨賺</li><li><strong>無背景刷新</strong>：cache 僅在被使用時刷新；TTL 過期 → 下次請求整個前綴重新 write（1.25×，非 read）</li><li>最低 cacheable：Opus 4.8 / Sonnet 4.6 = <strong>1,024 tokens</strong>；Haiku 4.5 = 4,096</li></ul><h3 id="_3-2-cache-pre-warming-降冷啟動體感" tabindex="-1">3.2 Cache pre-warming（降冷啟動體感） <a class="header-anchor" href="#_3-2-cache-pre-warming-降冷啟動體感" aria-label="Permalink to &quot;3.2 Cache pre-warming（降冷啟動體感）&quot;">​</a></h3><p>官方提供 <code>max_tokens:0</code> 觸發 cache write 而不產 output：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client.messages.create(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;claude-opus-4-8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">max_tokens</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  system</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cache_control&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ephemeral&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}],</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  messages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;warmup&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}])</span></span></code></pre></div><p>不相容：<code>stream=true</code> / extended thinking / structured outputs / <code>tool_choice:any|tool</code> / batch。</p><h3 id="_3-3-20-block-lookback" tabindex="-1">3.3 20-block lookback <a class="header-anchor" href="#_3-3-20-block-lookback" aria-label="Permalink to &quot;3.3 20-block lookback&quot;">​</a></h3><p>cache read 時從 breakpoint 往回最多掃 <strong>20 個 block</strong> 找最長匹配前綴；超出視為 miss → 需在舊 breakpoint 加 <code>cache_control</code>。每 request 最多 <strong>4 breakpoints</strong>。</p><h3 id="_3-4-cache-breaking-反模式-接合前作-dont-break-cache-論文" tabindex="-1">3.4 cache-breaking 反模式（接合前作 dont-break-cache 論文） <a class="header-anchor" href="#_3-4-cache-breaking-反模式-接合前作-dont-break-cache-論文" aria-label="Permalink to &quot;3.4 cache-breaking 反模式（接合前作 dont-break-cache 論文）&quot;">​</a></h3><p>timestamps / UUID / MCP server restart / mid-session 改 CLAUDE.md / 增刪 tool → 破壞靜態前綴 → cache miss → 成本 +30–60%。對應 CLAUDE.md context-management.md「mid-session 禁止切模型/增刪 tool/改 CLAUDE.md」。</p><hr><h2 id="_4-deferred-tool-toolsearch-機制-前作-gap-官方明文" tabindex="-1">4. Deferred-Tool / ToolSearch 機制（前作 GAP，官方明文） <a class="header-anchor" href="#_4-deferred-tool-toolsearch-機制-前作-gap-官方明文" aria-label="Permalink to &quot;4. Deferred-Tool / ToolSearch 機制（前作 GAP，官方明文）&quot;">​</a></h2><p>本 session 即為實例：~30 個 deferred tools 經 ToolSearch 按需載入。</p><h3 id="_4-1-觸發閾值" tabindex="-1">4.1 觸發閾值 <a class="header-anchor" href="#_4-1-觸發閾值" aria-label="Permalink to &quot;4.1 觸發閾值&quot;">​</a></h3><ul><li>tool definitions &gt; <strong>10K tokens</strong>，或 <strong>10+ tools</strong> → 自動 <code>defer_loading: true</code></li><li>Token 節省：50+ MCP 工具 77K → 8.7K tokens（<strong>-85%</strong>）；ToolSearch overhead 僅 ~500 tokens</li></ul><h3 id="_4-2-與-cache-的交互-關鍵-—-前作未答" tabindex="-1">4.2 與 cache 的交互（關鍵 — 前作未答） <a class="header-anchor" href="#_4-2-與-cache-的交互-關鍵-—-前作未答" aria-label="Permalink to &quot;4.2 與 cache 的交互（關鍵 — 前作未答）&quot;">​</a></h3><p>官方明文：</p><blockquote><p>&quot;Deferred tools are not included in the system-prompt prefix... the API appends a <code>tool_reference</code> block inline in the conversation... <strong>The prefix is untouched, so prompt caching is preserved.</strong>&quot;</p></blockquote><ul><li>deferred tool 的 schema <strong>不計入 cache prefix</strong>，被搜尋時注入 <strong>messages 層</strong>而非 system/tools 層 → <strong>不破壞 cache</strong></li><li>兩種搜尋：<code>regex</code>（≤200 字元 pattern）/ <code>bm25</code>（自然語言）；每次返回 3–5 個工具</li><li>約束：<strong>不可全部 deferred</strong>（至少一個非 deferred，否則 400）；strict mode 相容</li></ul><h3 id="_4-3-已知副作用-社群" tabindex="-1">4.3 已知副作用（社群） <a class="header-anchor" href="#_4-3-已知副作用-社群" aria-label="Permalink to &quot;4.3 已知副作用（社群）&quot;">​</a></h3><p>首輪不可用（#42148）、compact 後 reference 消失（#42835）、hook 衝突（#33073）、<code>--print</code> deadlock（#35262）。SkillSearch（skill 層 lazy-load）尚為 feature request。</p><hr><h2 id="_5-業界最佳實踐彙整-可執行-依優先序" tabindex="-1">5. 業界最佳實踐彙整（可執行，依優先序） <a class="header-anchor" href="#_5-業界最佳實踐彙整-可執行-依優先序" aria-label="Permalink to &quot;5. 業界最佳實踐彙整（可執行，依優先序）&quot;">​</a></h2><h3 id="_5-1-啟動層-sessionstart" tabindex="-1">5.1 啟動層（SessionStart） <a class="header-anchor" href="#_5-1-啟動層-sessionstart" aria-label="Permalink to &quot;5.1 啟動層（SessionStart）&quot;">​</a></h3><ol><li>升級至最新版（修 showSetupScreens async、Windows tasklist bug）</li><li><strong>SessionStart hook 維持 &lt; 1s</strong>（官方建議）；本機 session-init 592ms 可接受但 skill 掃描可快取</li><li>清 stale <code>git-worktrees.json</code>（Desktop 30–60s → 大幅改善）</li></ol><h3 id="_5-2-互動層-每-prompt-每-tool-call" tabindex="-1">5.2 互動層（每 prompt / 每 tool call） <a class="header-anchor" href="#_5-2-互動層-每-prompt-每-tool-call" aria-label="Permalink to &quot;5.2 互動層（每 prompt / 每 tool call）&quot;">​</a></h3><ol start="4"><li><strong>side-effect hook 加 <code>async:true</code></strong>（logging/audit/notification）— v2.1.45+</li><li><strong>security/validation/context hook 維持同步</strong>，改用 dispatcher 模式降 spawn（V8 50–80ms → IPC 2–5ms）</li><li>UserPromptSubmit hook 預設 timeout 30s（其他 600s）— 保持輕量</li><li>同一 event 多 hook → 單一 dispatcher（cached stdin），避免各自讀 stdin 造成 JSON corruption</li></ol><h3 id="_5-3-cache-層" tabindex="-1">5.3 Cache 層 <a class="header-anchor" href="#_5-3-cache-層" aria-label="Permalink to &quot;5.3 Cache 層&quot;">​</a></h3><ol start="8"><li>靜態前綴（CLAUDE.md/rules/tools）放最前不動 → 最大化 cache 命中</li><li>resume 間隔 &gt; 5min（TTL）→ 接受 cache miss 或 pre-warm；長閒置考慮 1hr TTL</li><li>不在 mid-session 改 CLAUDE.md / 切模型 / 增刪 tool</li></ol><h3 id="_5-4-mcp-tool-層" tabindex="-1">5.4 MCP / Tool 層 <a class="header-anchor" href="#_5-4-mcp-tool-層" aria-label="Permalink to &quot;5.4 MCP / Tool 層&quot;">​</a></h3><ol start="11"><li>ToolSearch（v2.1.7+ 預設開）已處理 token；wall-clock 連線待官方 <code>lazyConnect</code></li><li>project-scoped settings 限制 MCP server 清單</li><li>local agent 用 stdio transport（非 HTTP）</li></ol><hr><h2 id="_6-安全紅線-不可優化掉" tabindex="-1">6. 安全紅線（不可優化掉） <a class="header-anchor" href="#_6-安全紅線-不可優化掉" aria-label="Permalink to &quot;6. 安全紅線（不可優化掉）&quot;">​</a></h2><blockquote><p>⚠️ <strong>security hook 不可 async</strong>：<code>block-dangerous.sh</code>（阻擋危險命令）、<code>protect-sensitive-files.sh</code>（保護憑證）、<code>user-prompt-submit.sh</code>（context 注入）若改 async，會失去阻擋/保護/即時注入能力 — 違反 CLAUDE.md 安全紅線（§生產環境安全紅線 + R12 Fail Loud）。</p></blockquote><p>對這些 hook，正確路徑是**內部優化（dispatcher / 減 spawn / 加速 script）**而非 async。partition「async-safe vs must-stay-sync」是任何 hook 優化計劃的核心安全前提。</p><hr><h2 id="_7-附錄-arxiv-全文收錄" tabindex="-1">7. 附錄：arXiv 全文收錄 <a class="header-anchor" href="#_7-附錄-arxiv-全文收錄" aria-label="Permalink to &quot;7. 附錄：arXiv 全文收錄&quot;">​</a></h2><table tabindex="0"><thead><tr><th>arXiv</th><th>標題</th><th>收錄</th><th>相關性</th></tr></thead><tbody><tr><td>2502.15524</td><td>HydraServe: Cold Start Latency for Serverless LLM</td><td><strong>全文 PDF + 摘要</strong></td><td>間接（架構類比）</td></tr><tr><td>2512.16066</td><td>Cold-Start Anti-Patterns in Serverless（SANER 2026）</td><td><strong>全文 PDF + 摘要</strong></td><td>間接但概念強相關</td></tr><tr><td>2604.06664</td><td>Foundry: CUDA Graph Cold Start</td><td>摘要連結</td><td>間接（CUDA 層）</td></tr><tr><td>2512.01357</td><td>Tangram: Serverless LLM Loading</td><td>摘要連結</td><td>間接（GPU memory）</td></tr><tr><td>2601.06007</td><td>Don&#39;t Break the Cache（前作已收）</td><td>既有</td><td>cache 直接</td></tr><tr><td>2510.04618</td><td>Agentic Context Engineering（前作已收）</td><td>既有</td><td>context 直接</td></tr></tbody></table><hr><h2 id="來源清單" tabindex="-1">來源清單 <a class="header-anchor" href="#來源清單" aria-label="Permalink to &quot;來源清單&quot;">​</a></h2><p><strong>官方</strong>：<a href="https://code.claude.com/docs/en/memory" target="_blank" rel="noreferrer">memory</a> · <a href="https://platform.claude.com/docs/en/build-with-claude/prompt-caching" target="_blank" rel="noreferrer">prompt-caching</a> · <a href="https://platform.claude.com/docs/en/agents-and-tools/tool-use/tool-search-tool" target="_blank" rel="noreferrer">tool-search-tool</a> · <a href="https://code.claude.com/docs/en/hooks" target="_blank" rel="noreferrer">hooks</a> · <a href="https://www.anthropic.com/engineering/advanced-tool-use" target="_blank" rel="noreferrer">advanced-tool-use</a></p><p><strong>GitHub issues</strong>：#21261 #16257 #38346 #5186 #26521 #63251 #44536 #53224 #62327 · ruflo #1530</p><p><strong>社群/blog</strong>：blakecrosley.com（95 hooks）· softwarethug.com（ToolSearch lazy load）· implicator.ai（cache miss as incident）· claudecodecamp.com · TrueFoundry</p><p><strong>本機實測</strong>：8 hooks wall-clock + healthcheck 隔離計時 + auto-load byte（<code>wc -c</code>）+ live session-init elapsed</p>`,77)])])}const k=e(r,[["render",d]]);export{g as __pageData,k as default};
